export function mapColor(variant) {
    if (variant === "danger" || variant === "destructive" || variant === "error")
        return "error";
    if (variant === "success")
        return "success";
    if (variant === "warning")
        return "warning";
    if (variant === "secondary")
        return "info";
    if (variant === "informative" || variant === "info")
        return "info";
    return undefined;
}
export function mapButtonVariant(variant) {
    if (variant === "outline")
        return "outlined";
    if (variant === "ghost" || variant === "subtle" || variant === "transparent")
        return "text";
    return "contained";
}
export function mapButtonColor(variant) {
    if (variant === "danger" || variant === "destructive" || variant === "error")
        return "error";
    if (variant === "success")
        return "success";
    if (variant === "warning")
        return "warning";
    if (variant === "secondary")
        return "secondary";
    if (variant === "informative" || variant === "info")
        return "info";
    return "primary";
}
export function mapSize(size) {
    if (size === "large" || size === "lg")
        return "large";
    if (size === "small" || size === "sm" || size === "extra-small" || size === "xs")
        return "small";
    return "medium";
}
export function mapChipVariant(appearance, variant) {
    if (variant === "outline" || appearance === "outline")
        return "outlined";
    return "filled";
}
export function mapModalSize(size) {
    if (typeof size === "number")
        return size;
    if (size === "small" || size === "sm")
        return 360;
    if (size === "large" || size === "lg")
        return 900;
    if (size === "xl")
        return 1140;
    return 600;
}
