import colors from "tailwindcss/colors";
export const SHADCN_COLOR_STOPS = [
    50,
    100,
    200,
    300,
    400,
    500,
    600,
    700,
    800,
    900,
    950,
];
export const DEFAULT_SHADCN_PRESET_ID = "tailwind:slate";
export const builtinTailwindPaletteNames = [
    "slate",
    "gray",
    "zinc",
    "neutral",
    "stone",
    "red",
    "orange",
    "amber",
    "yellow",
    "lime",
    "green",
    "emerald",
    "teal",
    "cyan",
    "sky",
    "blue",
    "indigo",
    "violet",
    "purple",
    "fuchsia",
    "pink",
    "rose",
];
const fallbackDestructiveScale = normalizeScale(colors.red) ?? createScaleFromBaseColor("#ef4444");
function toTitle(value) {
    return value.charAt(0).toUpperCase() + value.slice(1);
}
function cssVarName(tokenName) {
    return tokenName.replace(/[A-Z]/g, (match) => `-${match.toLowerCase()}`);
}
function clamp(value, min, max) {
    return Math.min(max, Math.max(min, value));
}
function normalizeHex(value) {
    const raw = value.trim();
    const short = raw.match(/^#?([0-9a-f]{3})$/i)?.[1];
    if (short)
        return `#${short.split("").map((c) => c + c).join("")}`.toUpperCase();
    const long = raw.match(/^#?([0-9a-f]{6})$/i)?.[1];
    return long ? `#${long}`.toUpperCase() : undefined;
}
function parseHex(value) {
    const hex = normalizeHex(value);
    if (!hex)
        return undefined;
    const n = Number.parseInt(hex.slice(1), 16);
    return { r: (n >> 16) & 255, g: (n >> 8) & 255, b: n & 255 };
}
function rgbToHex(r, g, b) {
    return `#${[r, g, b]
        .map((part) => clamp(Math.round(part), 0, 255).toString(16).padStart(2, "0"))
        .join("")}`.toUpperCase();
}
function mix(color, targetColor, amount) {
    const source = parseHex(color);
    const target = parseHex(targetColor);
    if (!source || !target) {
        const sourceWeight = Math.round((1 - amount) * 1000) / 10;
        return `color-mix(in srgb, ${color} ${sourceWeight}%, ${targetColor})`;
    }
    return rgbToHex(source.r * (1 - amount) + target.r * amount, source.g * (1 - amount) + target.g * amount, source.b * (1 - amount) + target.b * amount);
}
export function isValidHexColor(value) {
    return !!normalizeHex(value);
}
export function normalizeColorValue(value) {
    const hex = normalizeHex(value);
    if (hex)
        return hex;
    return value.trim();
}
export function hexToCssHsl(value) {
    const rgb = parseHex(value);
    if (!rgb)
        return value.trim();
    const r = rgb.r / 255;
    const g = rgb.g / 255;
    const b = rgb.b / 255;
    const max = Math.max(r, g, b);
    const min = Math.min(r, g, b);
    let h = 0;
    let s = 0;
    const l = (max + min) / 2;
    if (max !== min) {
        const d = max - min;
        s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
        switch (max) {
            case r:
                h = (g - b) / d + (g < b ? 6 : 0);
                break;
            case g:
                h = (b - r) / d + 2;
                break;
            default:
                h = (r - g) / d + 4;
        }
        h /= 6;
    }
    return `hsl(${Math.round(h * 360)} ${Math.round(s * 1000) / 10}% ${Math.round(l * 1000) / 10}%)`;
}
export function readableTextColor(background) {
    const rgb = parseHex(background);
    if (!rgb)
        return "var(--aih-shadcn-foreground)";
    const luminance = (0.2126 * rgb.r + 0.7152 * rgb.g + 0.0722 * rgb.b) / 255;
    return luminance > 0.55 ? "#111827" : "#F9FAFB";
}
export function createScaleFromBaseColor(baseHex) {
    const base = normalizeHex(baseHex) ?? "#3B82F6";
    return {
        50: mix(base, "#FFFFFF", 0.95),
        100: mix(base, "#FFFFFF", 0.9),
        200: mix(base, "#FFFFFF", 0.76),
        300: mix(base, "#FFFFFF", 0.58),
        400: mix(base, "#FFFFFF", 0.32),
        500: base,
        600: mix(base, "#000000", 0.12),
        700: mix(base, "#000000", 0.28),
        800: mix(base, "#000000", 0.46),
        900: mix(base, "#000000", 0.62),
        950: mix(base, "#000000", 0.78),
    };
}
export function normalizeScale(scale) {
    if (!scale || typeof scale !== "object")
        return undefined;
    const out = {};
    for (const stop of SHADCN_COLOR_STOPS) {
        const value = scale[String(stop)];
        if (typeof value !== "string")
            return undefined;
        out[stop] = normalizeColorValue(value);
    }
    return out;
}
export function createSchemeFromScale(scale, radius = "0.5rem") {
    const destructive = fallbackDestructiveScale;
    return {
        radius,
        palette: scale,
        light: {
            background: scale[50],
            foreground: scale[950],
            card: mix(scale[50], scale[100], 0.55),
            cardForeground: scale[950],
            popover: "#FFFFFF",
            popoverForeground: scale[950],
            primary: scale[900],
            primaryForeground: scale[50],
            secondary: scale[100],
            secondaryForeground: scale[900],
            muted: scale[100],
            mutedForeground: scale[600],
            accent: scale[100],
            accentForeground: scale[900],
            destructive: destructive[600],
            destructiveForeground: destructive[50],
            border: scale[200],
            input: scale[200],
            ring: scale[500],
            chatAssistant: mix(scale[50], scale[100], 0.75),
            chatAssistantForeground: scale[950],
            chatAssistantBorder: scale[200],
        },
        dark: {
            background: scale[950],
            foreground: scale[50],
            card: scale[900],
            cardForeground: scale[50],
            popover: scale[950],
            popoverForeground: scale[50],
            primary: scale[200],
            primaryForeground: scale[950],
            secondary: scale[800],
            secondaryForeground: scale[50],
            muted: scale[800],
            mutedForeground: scale[300],
            accent: scale[800],
            accentForeground: scale[50],
            destructive: destructive[800],
            destructiveForeground: destructive[50],
            border: scale[800],
            input: scale[800],
            ring: scale[300],
            chatAssistant: mix(scale[950], scale[900], 0.45),
            chatAssistantForeground: scale[50],
            chatAssistantBorder: scale[800],
        },
    };
}
export function createSchemeFromBaseColor(baseHex, radius = "0.5rem") {
    return createSchemeFromScale(createScaleFromBaseColor(baseHex), radius);
}
export function buildBuiltinTailwindPresets() {
    const presets = {};
    for (const paletteName of builtinTailwindPaletteNames) {
        const scale = normalizeScale(colors[paletteName]);
        if (!scale)
            continue;
        const id = `tailwind:${paletteName}`;
        presets[id] = {
            id,
            title: toTitle(paletteName),
            description: `Tailwind ${paletteName} palette`,
            source: "builtin",
            scheme: createSchemeFromScale(scale),
        };
    }
    return presets;
}
export function buildAppSchemePresets(customSchemes) {
    const presets = {};
    for (const [name, scheme] of Object.entries(customSchemes ?? {})) {
        const id = `scheme:${name}`;
        presets[id] = {
            id,
            title: scheme.title ?? name,
            description: scheme.description,
            source: "app",
            scheme,
        };
    }
    return presets;
}
export function createCustomPresetFromStored(stored) {
    return {
        id: stored.id,
        title: stored.title,
        source: "custom",
        description: "Custom shadcn scheme",
        scheme: createSchemeFromBaseColor(stored.baseHex, stored.radius),
    };
}
function mergeModeTokens(tokens) {
    return Object.entries(tokens)
        .map(([key, value]) => `  --aih-shadcn-${cssVarName(key)}: ${hexToCssHsl(String(value))};`)
        .join("\n");
}
export function buildShadcnPresetStyles(preset) {
    const radius = preset.scheme.radius ?? "0.5rem";
    return `
.aih-shadcn-theme,
.aih-shadcn-portal-root {
  --aih-shadcn-radius: ${radius};
${mergeModeTokens(preset.scheme.light)}
}

.aih-shadcn-theme.dark,
.dark .aih-shadcn-theme:not(.light),
.aih-shadcn-portal-root.dark,
.dark .aih-shadcn-portal-root:not(.light),
html[data-theme="dark"] .aih-shadcn-portal-root:not(.light) {
${mergeModeTokens(preset.scheme.dark)}
}`;
}
export function getPresetPalette(preset) {
    return preset?.scheme.palette;
}
