import { createDarkTheme, createLightTheme, webDarkTheme, teamsDarkTheme, teamsLightTheme, teamsDarkV21Theme, teamsLightV21Theme, webLightTheme, createTeamsDarkTheme, } from "@fluentui/react-components";
export const baseFluentThemePresets = {
    web: {
        id: "web",
        title: "Web",
        getTheme: ({ mode }) => (mode === "dark" ? webDarkTheme : webLightTheme),
    },
    /*   azure: {
           id: "azure",
           title: "Azure",
           getTheme: ({ mode }) => (mode === "dark" ? AzureDarkTheme : AzureLightTheme),
       },*/
    teams: {
        id: "teams",
        title: "Teams",
        getTheme: ({ mode }) => (mode === "dark" ? teamsDarkTheme : teamsLightTheme),
    },
    teamsv21: {
        id: "teamsv21",
        title: "Teams v2.1",
        getTheme: ({ mode }) => (mode === "dark" ? teamsDarkV21Theme : teamsLightV21Theme),
    },
};
export function buildFluentThemePresets(brands) {
    const presets = { ...baseFluentThemePresets };
    for (const [brandName, variants] of Object.entries(brands ?? {})) {
        const id = `brand:${brandName}`;
        presets[id] = {
            id,
            title: brandName,
            getTheme: ({ mode }) => (mode === "dark" ?
                createDarkTheme(variants) : createLightTheme(variants)),
        };
        const teamsId = `teams:brand:${brandName}`;
        presets[teamsId] = {
            id: teamsId,
            title: brandName + " Teams",
            getTheme: ({ mode }) => (mode === "dark" ?
                createTeamsDarkTheme(variants) : createLightTheme(variants)),
        };
    }
    return presets;
}
